    37	        public FromArrayStreamer(T[] items) {
    38	            this.items = items;
    39	            this.index = -1;
    40	        }
    41	
    42	        @Override
    43	        public @NonNull CompletionStage<Boolean> next() {
    44	            if (++index >= items.length) {
    45	                return NEXT_FALSE;
    46	            }
    47	            if (current() == null) {
    48	                return CompletableFuture.failedFuture(createNullError(index));
    49	            }
    50	            return NEXT_TRUE;
    51	        }
    52	
    53	        static NullPointerException createNullError(int index) {
    54	            return new NullPointerException("Item at index " + index + " is null.");
    55	        }
    56	
    57	        @Override
    58	        public boolean nextSync() {
    59	            if (++index < items.length) {
    60	                if (current() == null) {
    61	                    throw createNullError(index);
    62	                }
    63	                return true;
    64	            };
    65	            return false;
    66	        }
    67	
