    69	        public @NonNull T current() {
    70	            return items[index];
    71	        }
    72	
    73	        @Override
    74	        public @NonNull CompletionStage<Void> finish() {
    75	            index = items.length;
    76	            return FINISHED;
    77	        }
    78	
    79	        @Override
    80	        public @NonNull T elementAt(long index) throws Throwable {
    81	            var v = items[(int)index];
    82	            if (v ==  null) {
    83	                throw createNullError((int)index);
    84	            }
    85	            return v;
    86	        }
